// @manicat-dependencies react-native-svg
import { useState } from "react";
import { Pressable, StyleSheet, Text, View } from "react-native";
import type { LayoutChangeEvent, StyleProp, TextStyle, ViewProps, ViewStyle } from "react-native";
import Svg, { Path } from "react-native-svg";
import { bandPath, linearScale } from "../lib/chart";
import { metrics, useTokens } from "../lib/rn-tokens";

export interface StreamgraphSeries {
  key: string;
  label: string;
  color?: string;
}

export interface StreamgraphDatum {
  key: string;
  label: string;
  axisLabel?: string;
  values: Record<string, number | undefined>;
}

export interface StreamgraphProps extends Omit<ViewProps, "children"> {
  data: StreamgraphDatum[];
  series: StreamgraphSeries[];
  label: string;
  unit?: string;
  height?: number;
  /** `silhouette` centres the stack; `zero` sits it on a baseline. */
  offset?: "silhouette" | "zero";
  formatValue?: (value: number, series: StreamgraphSeries) => string;
  legend?: boolean;
  emptyLabel?: string;
  /** Extend the inner, named parts of the chart: readout, legend or axis. The React Native counterpart of `classNames`. */
  styles?: {
    readout?: StyleProp<TextStyle>;
    legend?: StyleProp<ViewStyle>;
    axis?: StyleProp<TextStyle>;
  };
}

/** Stacked flowing areas showing how the mix of series changes over time. Press a band or a legend entry to focus it. */
export function Streamgraph({ data, series, label, unit = "", height = 220, offset = "silhouette", formatValue = (n) => n.toLocaleString(), legend = true, emptyLabel = "No data yet", style, styles: parts, ...props }: StreamgraphProps) {
  const tokens = useTokens();
  const [width, setWidth] = useState(0);
  const [focus, setFocus] = useState<string | null>(null);
  if (data.length === 0) return <Text style={{ color: tokens.textMuted, fontSize: metrics.text.sm }}>{emptyLabel}</Text>;

  const totals = data.map((datum) => series.reduce((sum, entry) => sum + (datum.values[entry.key] ?? 0), 0));
  const peak = Math.max(...totals, 1);
  const x = linearScale([0, Math.max(1, data.length - 1)], [0, width]);
  const y = linearScale(offset === "zero" ? [0, peak] : [-peak / 2, peak / 2], [height, 0]);
  const base = data.map((_, index) => (offset === "zero" ? 0 : -totals[index] / 2));
  const color = (entry: StreamgraphSeries) => entry.color ?? tokens.series[series.indexOf(entry) % 4];
  const bands = series.map((entry, at) => {
    const lower = base.map((value, index) => value + series.slice(0, at).reduce((sum, other) => sum + (data[index].values[other.key] ?? 0), 0));
    const upper = lower.map((value, index) => value + (data[index].values[entry.key] ?? 0));
    const d = bandPath(upper.map((value, index): [number, number] => [x(index), y(value)]), lower.map((value, index): [number, number] => [x(index), y(value)]), "smooth");
    return { entry, d };
  });
  const picked = series.find((entry) => entry.key === focus);

  return (
    <View {...props} accessible accessibilityLabel={`${label}. ${series.map((entry) => entry.label).join(", ")}`} style={[{ alignSelf: "stretch", gap: metrics.space[2] }, style]}>
      <Text style={{ color: tokens.foreground, fontSize: metrics.text.sm, fontWeight: "500" }}>{label}</Text>
      <Text style={[{ color: tokens.textSecondary, fontSize: metrics.text.xs, minHeight: 16 }, parts?.readout]}>{picked ? `${picked.label}: peak ${formatValue(Math.max(...data.map((datum) => datum.values[picked.key] ?? 0)), picked)}${unit ? ` ${unit}` : ""}` : " "}</Text>
      <View onLayout={(event: LayoutChangeEvent) => setWidth(event.nativeEvent.layout.width)} style={{ height }}>
        {width > 0 ? (
          <Svg width={width} height={height}>
            {bands.map(({ entry, d }) => (
              <Path key={entry.key} d={d} fill={color(entry)} fillOpacity={focus === null || focus === entry.key ? 0.85 : 0.2} onPress={() => setFocus(focus === entry.key ? null : entry.key)} />
            ))}
          </Svg>
        ) : null}
      </View>
      <View style={local.axis}>
        {data.filter((datum) => datum.axisLabel).map((datum) => (
          <Text key={datum.key} style={[{ color: tokens.textMuted, fontSize: 11 }, parts?.axis]}>{datum.axisLabel}</Text>
        ))}
      </View>
      {legend ? (
        <View style={[local.legend, parts?.legend]}>
          {series.map((entry) => (
            <Pressable key={entry.key} accessibilityRole="button" accessibilityState={{ selected: focus === entry.key }} onPress={() => setFocus(focus === entry.key ? null : entry.key)} style={local.legendItem}>
              <View style={[local.swatch, { backgroundColor: color(entry) }]} />
              <Text style={{ color: tokens.foreground, fontSize: metrics.text.xs }}>{entry.label}</Text>
            </Pressable>
          ))}
        </View>
      ) : null}
    </View>
  );
}

const local = StyleSheet.create({
  axis: { flexDirection: "row", justifyContent: "space-between" },
  legend: { flexDirection: "row", flexWrap: "wrap", gap: metrics.space[3] },
  legendItem: { flexDirection: "row", alignItems: "center", gap: 6 },
  swatch: { width: 10, height: 10, borderRadius: 5 },
});

export default Streamgraph;

import { useColorScheme } from "react-native";

/** The Manicat UI design tokens as React Native values. Same names and meaning as registry/foundation.css. */
export interface ManicatTokens {
  background: string;
  surface: string;
  surfaceMuted: string;
  foreground: string;
  textSecondary: string;
  textMuted: string;
  border: string;
  borderStrong: string;
  accent: string;
  accentStrong: string;
  accentSubtle: string;
  success: string;
  warning: string;
  danger: string;
  controlOn: string;
  controlTrack: string;
  controlThumb: string;
  controlThumbOn: string;
  /** Four distinguishable colours for chart series, the counterpart of --series-1 to --series-4. */
  series: [string, string, string, string];
}

export const lightTokens: ManicatTokens = {
  background: "#ffffff",
  surface: "#ffffff",
  surfaceMuted: "#f6f6f6",
  foreground: "#1b1b1b",
  textSecondary: "#6e6e6e",
  textMuted: "#8f8f8f",
  border: "#ebebeb",
  borderStrong: "#c9c9c9",
  accent: "#4a4a4a",
  accentStrong: "#303030",
  accentSubtle: "rgba(74, 74, 74, 0.1)",
  success: "#1f8a4c",
  warning: "#b8741a",
  danger: "#d03b3b",
  controlOn: "#2c2c2c",
  controlTrack: "#e2e2e2",
  controlThumb: "#ffffff",
  controlThumbOn: "#ffffff",
  series: ["#1f7dcf", "#7128a5", "#e58f00", "#009e84"],
};

export const darkTokens: ManicatTokens = {
  background: "#2b2b2b",
  surface: "#303030",
  surfaceMuted: "#3c3c3c",
  foreground: "#f1f1f1",
  textSecondary: "#c4c4c4",
  textMuted: "#a0a0a0",
  border: "#454545",
  borderStrong: "#5c5c5c",
  accent: "#cfcfcf",
  accentStrong: "#e6e6e6",
  accentSubtle: "rgba(207, 207, 207, 0.13)",
  success: "#5fd48a",
  warning: "#f0b95c",
  danger: "#ff8a80",
  controlOn: "#ececec",
  controlTrack: "#515151",
  controlThumb: "#f4f4f4",
  controlThumbOn: "#2b2b2b",
  series: ["#55adff", "#9c37be", "#e66e00", "#00a861"],
};

/** Shape and rhythm shared by every component, in density-independent pixels. */
export const metrics = {
  radiusControl: 18,
  radiusPill: 9999,
  controlHeight: { sm: 36, md: 44, lg: 50 },
  space: { 1: 4, 2: 8, 3: 12, 4: 16, 5: 20 },
  text: { xs: 12, sm: 14, lg: 18 },
} as const;

/** The tokens for the device's current colour scheme. Wrap the app in your own provider if you manage the theme yourself. */
export function useTokens(): ManicatTokens {
  return useColorScheme() === "dark" ? darkTokens : lightTokens;
}

/**
 * Geometry shared by the chart ports (React Native with react-native-svg, Vue with inline SVG). Pure functions: they turn data
 * into scales, ticks and SVG path strings, and leave drawing to each framework.
 */

export type Point = [number, number];

export interface Scale {
  (value: number): number;
  domain: [number, number];
  range: [number, number];
}

export function linearScale(domain: [number, number], range: [number, number]): Scale {
  const [d0, d1] = domain;
  const [r0, r1] = range;
  const scale = ((value: number) => (d1 === d0 ? (r0 + r1) / 2 : r0 + ((value - d0) / (d1 - d0)) * (r1 - r0))) as Scale;
  scale.domain = domain;
  scale.range = range;
  return scale;
}

/** A tidy upper bound for a data maximum: 1, 2, 2.5, 5 or 10 times a power of ten. */
export function niceMax(max: number): number {
  if (max <= 0) return 1;
  const power = Math.pow(10, Math.floor(Math.log10(max)));
  const fraction = max / power;
  const step = fraction <= 1 ? 1 : fraction <= 2 ? 2 : fraction <= 2.5 ? 2.5 : fraction <= 5 ? 5 : 10;
  return step * power;
}

/** `count` evenly spaced tick values from 0 to a nice maximum. */
export function ticks(max: number, count = 4): number[] {
  const top = niceMax(max);
  return Array.from({ length: count + 1 }, (_, index) => (top / count) * index);
}

export const compact = (n: number) => new Intl.NumberFormat("en-US", { notation: "compact", maximumFractionDigits: 1 }).format(n);

/** A straight polyline, or a smooth curve through the points (monotone-ish Catmull-Rom converted to cubic Béziers). */
export function linePath(points: Point[], curve: "smooth" | "linear" = "smooth"): string {
  if (points.length === 0) return "";
  if (points.length === 1 || curve === "linear") return points.map(([x, y], index) => `${index ? "L" : "M"}${x.toFixed(2)},${y.toFixed(2)}`).join("");
  let d = `M${points[0][0].toFixed(2)},${points[0][1].toFixed(2)}`;
  for (let index = 0; index < points.length - 1; index += 1) {
    const p0 = points[index - 1] ?? points[index];
    const p1 = points[index];
    const p2 = points[index + 1];
    const p3 = points[index + 2] ?? p2;
    const c1: Point = [p1[0] + (p2[0] - p0[0]) / 6, p1[1] + (p2[1] - p0[1]) / 6];
    const c2: Point = [p2[0] - (p3[0] - p1[0]) / 6, p2[1] - (p3[1] - p1[1]) / 6];
    d += `C${c1[0].toFixed(2)},${c1[1].toFixed(2)} ${c2[0].toFixed(2)},${c2[1].toFixed(2)} ${p2[0].toFixed(2)},${p2[1].toFixed(2)}`;
  }
  return d;
}

/** The area between a line and the baseline `y0`. */
export function areaPath(points: Point[], y0: number, curve: "smooth" | "linear" = "smooth"): string {
  if (points.length === 0) return "";
  const last = points[points.length - 1];
  return `${linePath(points, curve)}L${last[0].toFixed(2)},${y0.toFixed(2)}L${points[0][0].toFixed(2)},${y0.toFixed(2)}Z`;
}

/** A band between an upper and a lower line, for stacked areas. */
export function bandPath(upper: Point[], lower: Point[], curve: "smooth" | "linear" = "smooth"): string {
  if (upper.length === 0) return "";
  const back = [...lower].reverse();
  return `${linePath(upper, curve)}L${back[0][0].toFixed(2)},${back[0][1].toFixed(2)}${linePath(back, curve).replace(/^M[^CL]*/, "")}Z`;
}

/** A ring segment from `a0` to `a1` radians (0 is 12 o'clock, clockwise). */
export function arcPath(cx: number, cy: number, outer: number, inner: number, a0: number, a1: number): string {
  const sweep = Math.min(a1 - a0, Math.PI * 2 - 0.0001);
  const end = a0 + sweep;
  const point = (r: number, a: number): Point => [cx + r * Math.sin(a), cy - r * Math.cos(a)];
  const [x0, y0] = point(outer, a0);
  const [x1, y1] = point(outer, end);
  const [x2, y2] = point(inner, end);
  const [x3, y3] = point(inner, a0);
  const large = sweep > Math.PI ? 1 : 0;
  return `M${x0.toFixed(2)},${y0.toFixed(2)}A${outer},${outer} 0 ${large} 1 ${x1.toFixed(2)},${y1.toFixed(2)}L${x2.toFixed(2)},${y2.toFixed(2)}A${inner},${inner} 0 ${large} 0 ${x3.toFixed(2)},${y3.toFixed(2)}Z`;
}

export interface Rect {
  x: number;
  y: number;
  width: number;
  height: number;
}

/** Squarified treemap: lays `values` out in `rect`, keeping cells close to square. Returns one rect per value, in input order. */
export function squarify(values: number[], rect: Rect): Rect[] {
  const total = values.reduce((sum, value) => sum + value, 0);
  const out: Rect[] = new Array(values.length);
  if (total <= 0) return values.map(() => ({ ...rect, width: 0, height: 0 }));
  const order = values.map((value, index) => ({ value, index })).sort((a, b) => b.value - a.value);
  let free = { ...rect };
  let remaining = total;
  let row: typeof order = [];

  const worst = (items: typeof order, side: number, scale: number) => {
    const sum = items.reduce((s, item) => s + item.value * scale, 0);
    const max = Math.max(...items.map((item) => item.value * scale));
    const min = Math.min(...items.map((item) => item.value * scale));
    return Math.max((side * side * max) / (sum * sum), (sum * sum) / (side * side * min));
  };

  const place = (items: typeof order, scale: number) => {
    const sum = items.reduce((s, item) => s + item.value * scale, 0);
    const horizontal = free.width >= free.height;
    const thickness = sum / (horizontal ? free.height : free.width);
    let offset = 0;
    for (const item of items) {
      const length = (item.value * scale) / thickness;
      out[item.index] = horizontal ? { x: free.x, y: free.y + offset, width: thickness, height: length } : { x: free.x + offset, y: free.y, width: length, height: thickness };
      offset += length;
    }
    free = horizontal ? { x: free.x + thickness, y: free.y, width: free.width - thickness, height: free.height } : { x: free.x, y: free.y + thickness, width: free.width, height: free.height - thickness };
    remaining -= items.reduce((s, item) => s + item.value, 0);
  };

  for (const item of order) {
    const scale = (free.width * free.height) / remaining;
    const side = Math.min(free.width, free.height);
    if (row.length === 0 || worst([...row, item], side, scale) <= worst(row, side, scale)) row.push(item);
    else {
      place(row, scale);
      row = [item];
    }
  }
  if (row.length) place(row, (free.width * free.height) / remaining);
  return out;
}
